{
    struct sas_hba *sas_hba = cmd->device->host->hostdata;
    struct sas_rphy *rphy = cmd->device->sas_rphy;
    struct sas_device *sas_dev = cmd->device->hostdata;

    if (unlikely(sas_dev->sata_dev)) {
        /* Defer to libata error handler for SATA devices */
        cmd->scsi_done(cmd);
        return;
    }

    spin_lock(&cmd->host->host_lock);
    list_del_init(&cmd->eh_list);
    list_add_tail(&cmd->done_list, &cmd->host->done_head);
    spin_unlock(&cmd->host->host_lock);

    cmd->scsi_done(cmd);
}

void scsi_abort_complete(struct scsi_cmnd *cmd)
{
    struct sas_ha_struct *ha = cmd->device->host->hostdata;
    struct sas_rphy *rphy = dev_to_rphy(cmd->device->sdev_gendev.parent);
    struct sas_phy *phy;
    struct asd_sas_port *port;

    if (rphy)
        phy = rphy->phy;
    else
        phy = cmd->device->sas_rphy->phy;

    port = phy->port;

    if (cmd->eh_flags & SCSI_EH_SAS_ABORT) {
        if (cmd->device->type == TYPE_DISK && scsi_is_sas_dev_sata(cmd->device)) {
            cmd->eh_flags &= ~SCSI_EH_SAS_ABORT;
            cmd->done = scsi_error_put;
            scsi_end_request(cmd, 0, 0);
            return;
        }

        port->eh_active = 0;
        cmd->done = scsi_error_put;
        scsi_end_request(cmd, 0, 0);
    }
}

void scsi_abort_command_handler(struct scsi_cmnd *cmd)
{
    struct sas_ha_struct *ha = cmd->device->host->hostdata;
    struct sas_rphy *rdev = cmd->device->hostdata;
    struct sas_device *sas_dev = rdev->sas_device;

    if (sas_dev->sata_dev) {
        /* Defer to libata error handler for SATA devices */
        scsi_ata_device_error(cmd);
        return;
    }

    /* Ensure no race with completions from low-level driver */
    spin_lock_irq(&ha->lock);
    list_del_init(&cmd->eh_list);
    spin_unlock_irq(&ha->lock);

    scsi_finish_command(cmd);
}

void scsi_abort_command_handler(struct scsi_cmnd *cmd)
{
    struct sas_ha_struct *ha = cmd->device->host->hostdata;
    struct sas_rphy *rdev = cmd->device->hostdata;
    struct sas_device *sas_dev = rdev->sas_device;

    /* Ensure the command is not racing with any completions from the low-level driver */
    spin_lock_irq(&cmd->done_lock);

    if (sas_dev && sas_dev->sata_dev) {
        /* Defer to libata error handler for SATA devices */
        cmd->scsi_done(cmd);
    } else {
        /* Complete the command and move to finished list */
        cmd->result = DID_ABORT << 16;
        scsi_dma_unmap(cmd);
        cmd->scsi_done(cmd);
        list_del(&cmd->eh_list);
    }

    spin_unlock_irq(&cmd->done_lock);
}

void scsi_eh_finish_abort(struct scsi_cmnd *cmd)
{
    struct Scsi_Host *shost = cmd->device->host;
    struct sas_rphy *rphy = dev_to_rphy(cmd->device->sdev_gendev.parent);
    struct sas_device *sas_dev = rphy ? to_sas_device(&rphy->dev) : NULL;
    struct domain_device *dev = sas_dev ? sas_dev->sas_device : NULL;

    if (!dev)
        return;

    if (sata_dev_ioctl(dev->sata_dev, NULL, 0)) {
        /* Defer to libata error handler if it's a SATA device */
        scsi_ata_end_eh(cmd);
    } else {
        /* Move the command to the list of finished commands */
        list_move_tail(&cmd->eh_entry, &shost->eh_done_q);
    }
}
